mapper.select:
SELECT ko.id, ko.use_org_id AS useOrgId, ko.use_org_name AS useOrgName, krp.id AS kingdeeUserRefPostId, krp.kingdee_department_id AS kingdeeDepartmentId, kd.kingdee_dept_name AS kingdeeDepartmentName, kp.name AS userPostName, su.user_name AS userName, ko.code as operatorCode, ko.disabled FROM kingdee_operator_ref_post ko LEFT JOIN kingdee_user_ref_post krp ON krp.id = ko.user_post_id AND krp.is_deleted = FALSE LEFT JOIN kingdee_department kd ON kd.id = krp.kingdee_department_id AND kd.is_deleted = FALSE LEFT JOIN kingdee_post kp ON kp.id = krp.kingdee_post_id AND kp.is_deleted = FALSE LEFT JOIN sys_user_info su ON su.uid = krp.erp_user_id WHERE ko.is_deleted = FALSE AND ko.type_code = #{params.typeCode} AND
${params.sqlMap.default}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
ko.id desc

SELECT ko.id,
       ko.code AS userPostCode,
       kd.kingdee_dept_code AS  deptCode
FROM kingdee_operator_ref_post ko
LEFT JOIN kingdee_user_ref_post krp ON krp.id = ko.user_post_id AND krp.is_deleted = FALSE and ko.use_org_id = krp.use_org_id
LEFT JOIN kingdee_department kd ON kd.id = krp.kingdee_department_id AND kd.is_deleted = FALSE and kd.use_org_id = ko.use_org_id
WHERE ko.is_deleted = FALSE
AND ko.type_code = #{params.businessOperatorType}
AND krp.erp_user_id=#{params.userId}

    AND   ko.use_org_id=#{params.orgId}


    AND  ko.use_org_id=(SELECT id FROM  sys_accounting_company  WHERE code=#{params.orgCode} LIMIT 1)


    AND kd.erp_dept_id = #{params.salesDeptId}

LIMIT 1

SELECT ko.id, ko.type_code, krp.code AS userPostCode, kd.kingdee_dept_code AS deptCode, ko.use_org_id AS orgId, krp.erp_user_id AS userId FROM kingdee_operator_ref_post ko INNER JOIN kingdee_user_ref_post krp ON krp.id = ko.user_post_id AND krp.is_deleted = FALSE INNER JOIN kingdee_department kd ON kd.id = krp.kingdee_department_id AND kd.is_deleted = FALSE WHERE ko.is_deleted = FALSE
AND krp.erp_user_id IN
#{item}
